#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long min_v, x; scanf("%lld", &min_v);
    for (int i = 1; i < n; i++) { scanf("%lld", &x); if (x < min_v) min_v = x; }
    printf("%lld\n", min_v);
    return 0;
}

