code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long minV = sc.nextLong();
            for (int i = 1; i < n; i++) {
                long x = sc.nextLong();
                if (x < minV) minV = x;
            }
            System.out.println(minV);
        }
    }
}

