const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    let minV = BigInt(toks[1]);
    for (let i = 2; i <= n; i++) {
        const x = BigInt(toks[i]);
        if (x < minV) minV = x;
    }
    console.log(minV.toString());
}
main();

